def pile_vide():
    return {"sommet": None}
def est_vide(p):
    return p["sommet"] is None
def empiler(p, element):
    p["sommet"] = (element, p["sommet"])
def depiler(p):
    element, p["sommet"] = p["sommet"]
    return element
p = pile_vide()
for v in [3, 8]:
    empiler(p, v)
assert sommet(p) == 8, "Avec une autre implémentation, sommet(p) doit toujours renvoyer 8"
_sortis = []
while not est_vide(p):
    _sortis.append(depiler(p))
assert _sortis == [8, 3], "Avec une autre implémentation, la pile doit rester intacte"

def file_vide():
    return {"entree": [], "sortie": []}
def est_vide(f):
    return f["entree"] == [] and f["sortie"] == []
def enfiler(f, element):
    f["entree"].append(element)
def defiler(f):
    if f["sortie"] == []:
        while f["entree"] != []:
            f["sortie"].append(f["entree"].pop())
    return f["sortie"].pop()
f = file_vide()
for v in [5, 1, 4, 2]:
    enfiler(f, v)
assert somme(f) == 12, "Avec une autre implémentation, somme(f) doit toujours renvoyer 12 pour la file 5 1 4 2"
